import ast,os,collections,hashlib,re
files=[os.path.join(r,f) for r,d,fs in os.walk('.') for f in fs if f.endswith('.py') and not f.startswith('test_') and f!='conftest.py']
# 1 dup function bodies
h=collections.defaultdict(list)
for f in files:
    t=ast.parse(open(f,encoding='utf-8').read())
    for n in ast.walk(t):
        if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.end_lineno-n.lineno>=5:
            body=ast.dump(ast.Module(body=n.body,type_ignores=[]))
            h[hashlib.md5(body.encode()).hexdigest()].append((f,n.name,n.lineno))
print("dup bodies:",[v for v in h.values() if len(v)>1])
# 2 same name functions across modules
names=collections.defaultdict(list)
for f in files:
    t=ast.parse(open(f,encoding='utf-8').read())
    for n in t.body:
        if isinstance(n,ast.FunctionDef) and not n.name.startswith('__') and n.name!='main':
            names[n.name].append((f,n.lineno,n.end_lineno-n.lineno+1))
print("same-name:")
for k,v in names.items():
    if len(v)>1 and any(x[2]>=4 for x in v): print(k,v)
# 3 duplicate line windows (8 non-trivial consecutive normalized lines)
W=8
win=collections.defaultdict(set)
for f in files:
    L=[re.sub(r'\s+',' ',l.strip()) for l in open(f,encoding='utf-8').read().split('\n')]
    idx=[(i,l) for i,l in enumerate(L) if l and not l.startswith('#') and len(l)>8]
    for j in range(len(idx)-W):
        key='\n'.join(l for _,l in idx[j:j+W])
        win[key].add((f,idx[j][0]+1))
res=[v for v in win.values() if len({x[0] for x in v})>1 or len(v)>1]
# merge by file pair
seen=collections.Counter()
for v in res:
    seen[tuple(sorted(v))[0:2]]+=1
for k,c in sorted(seen.items(),key=lambda x:-x[1])[:25]: print(c,k)
